actualRule.text:
def(
    "삼각비의 활용",
    "03",
    "실생활에서 직각삼각형의 변의 길이의 활용 ⑴",
    SEC.활용,
    "응용",
    (rng) =>
      attempt(200, () => {
        const theta = pick(rng, [30, 45, 60] as const);
        const d = pick(rng, [6, 8, 9, 10, 12, 15, 18, 20] as const);
        const mode = intBetween(rng, 0, 2);
        const sinT = exact(0, theta)!;
        const cosT = exact(1, theta)!;
        const tanT = exact(2, theta)!;
        const ds = surd(d, 1, 1);
        const res =
          mode === 0
            ? surdMul(ds, tanT)
            : mode === 1
              ? surdDiv(ds, cosT)
              : surdMul(ds, sinT);
        if (res.d !== 1 || res.n > 90) return null;
        const height =
          mode === 2
            ? surdValue(res)
            : mode === 0
              ? surdValue(res)
              : d * Math.tan(theta * DEG);
        const ground = mode === 2 ? d * Math.cos(theta * DEG) : d;
        const scene = [
          {
            content: `지면에 수직으로 서 있는 나무의 밑동에서 $${d}\\,\\mathrm{m}$ 떨어진 지점에서 나무의 꼭대기를 올려본각의 크기가 $${theta}^\\circ$이었다. 이 나무의 높이를 구하시오.`,
            solution: `나무의 높이를 $h\\,\\mathrm{m}$라 하면 $\\tan ${theta}^\\circ=\\dfrac{h}{${d}}$이다.\n따라서 $h=${d}\\times\\tan ${theta}^\\circ=${surdText(res)}$이므로 나무의 높이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "BC",
          },
          {
            content: `벽에 사다리를 기대어 놓았더니 사다리가 지면과 이루는 각의 크기가 $${theta}^\\circ$이고, 사다리의 아래 끝이 벽에서 $${d}\\,\\mathrm{m}$ 떨어져 있었다. 이 사다리의 길이를 구하시오.`,
            solution: `사다리의 길이를 $l\\,\\mathrm{m}$라 하면 $\\cos ${theta}^\\circ=\\dfrac{${d}}{l}$이다.\n따라서 $l=\\dfrac{${d}}{${surdText(cosT)}}=${surdText(res)}$이므로 사다리의 길이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "BC",
          },
          {
            content: `길이가 $${d}\\,\\mathrm{m}$인 실을 모두 풀어 연을 날렸더니 실이 지면과 이루는 각의 크기가 $${theta}^\\circ$이었다. 실이 팽팽하다고 할 때, 지면에서 연까지의 높이를 구하시오.`,
            solution: `연까지의 높이를 $h\\,\\mathrm{m}$라 하면 $\\sin ${theta}^\\circ=\\dfrac{h}{${d}}$이다.\n따라서 $h=${d}\\times\\sin ${theta}^\\circ=${surdText(res)}$이므로 연까지의 높이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "CA",
          },
        ][mode]!;
        return {
          content: scene.content,
          answer: `$${surdText(res)}\\,\\mathrm{m}$`,
          solution: scene.solution,
          facts: { theta, d, mode, an: res.n, ar: res.r },
          figureSpec: figRight({
            vert: r2(height),
            horz: r2(ground),
            angC: `${theta}°`,
            dims: { [scene.dimKey]: `${d} m` },
          }),
        };
      }),
  ),
